"""Clip-specific on-screen headlines for the local Arctic video pipeline.

Usage (on agentlab):
  python add_headlines.py process '19-day-solo-video-1-*-styled.mp4'
  python add_headlines.py generate '19-day-solo-video-1-*-styled.mp4'
  python add_headlines.py render '19-day-solo-video-1-*-styled.mp4'
  python add_headlines.py render '19-day-solo-video-1-*-styled.mp4' --force
  python add_headlines.py install

"process" generates a clip-specific headline and renders an upload copy.
If the transcript is too vague or Ollama fails, the clip is flagged for
human review rather than inventing a headline.
"install" backs up and updates run_pipeline.py to invoke "process" for
EACH clip after styled-caption rendering succeeds.
"""

import base64
import json
import py_compile
import re
import shutil
import subprocess
import sys
import textwrap
from pathlib import Path

ROOT = Path(__file__).resolve().parent
FINISHED = ROOT / "finished"
SUBTITLES = ROOT / "subtitles"
HEADLINES = ROOT / "headlines"
REVIEW = HEADLINES / "review-needed"
MODEL = "qwen3:4b"
FONT = Path("/usr/share/fonts/truetype/lato/Lato-Bold.ttf")


# These are rendered PNG emoji assets, not font files. They render reliably in FFmpeg.
EMOJI_PNG = {
    "lightning": "",
    "siren": "",
    "snow": "",
    "wave": "",
    "movie": "",
}


def icon_name(headline: str) -> str:
    """Select a contextual visual icon from the actual clip headline."""
    text = headline.upper()
    if any(word in text for word in ("THUNDER", "LIGHTNING", "STORM", "FLASH")):
        return "lightning"
    if any(word in text for word in ("BEAR SPRAY", "BEAR", "ACCIDENT", "INJURY", "DANGER")):
        return "siren"
    if any(word in text for word in ("ICE", "SNOW", "FREEZ", "COLD", "BLIZZARD")):
        return "snow"
    if any(word in text for word in ("WATER", "RIVER", "LAKE", "BOAT", "CANO", "PADDLE")):
        return "wave"
    return "movie"


def icon_file(headline: str) -> Path:
    """Extract an image icon locally; no emoji-font dependency on agentlab."""
    name = icon_name(headline)
    path = HEADLINES / "icons" / f"{name}.png"
    path.parent.mkdir(parents=True, exist_ok=True)
    if not path.is_file():
        path.write_bytes(base64.b64decode(EMOJI_PNG[name]))
    return path


def spoken_words(srt_file: Path) -> str:
    lines = srt_file.read_text(encoding="utf-8-sig").splitlines()
    return " ".join(
        line.strip()
        for line in lines
        if line.strip() and not line.strip().isdigit() and "-->" not in line
    )


def normalize_headline(value) -> str:
    headline = re.sub(r"\s+", " ", str(value)).strip(' "\'\u201c\u201d').upper()
    if not (3 <= len(headline.split()) <= 11 and 12 <= len(headline) <= 62):
        raise ValueError("headline must be 3-11 words and 12-62 characters")
    if any(c in headline for c in "\n{}[]"):
        raise ValueError("headline contains unsupported characters")
    return headline


def generate_headline(transcript: str) -> str:
    from ollama import chat  # Only needed when we actually generate a headline.

    if not transcript.strip():
        raise ValueError("the clip has no spoken dialogue")

    last_error = ""
    for attempt in (1, 2):
        try:
            prompt = (
                "Write exactly ONE compelling on-screen hook for THIS clip. "
                "Base it only on the supplied transcript. Name the specific event, "
                "problem, choice, or revelation discussed. Do not fabricate events, "
                "danger, claims, dialogue, or emotions. Never use generic expedition "
                "titles or clickbait unrelated to the transcript. "
                "Use 4 to 9 words and at most 48 characters; uppercase. "
                'Reply with ONLY a JSON object: {"headline":"YOUR SHORT TITLE"}. '
                'Always identify the most specific useful fact or advice '
                'present in the transcript and create a headline about it. '
                'If the transcript is vague, describe the actual topic '
                'without inventing additional details. '
                'Do not return an empty headline. '
            )
            if attempt == 2:
                prompt += "Your previous reply was unusable. Keep it shorter and specific. "
            response = chat(
                model=MODEL,
                think=False,
                format="json",
                options={"num_predict": 120, "temperature": 0.3, "repeat_penalty": 1.2},
                messages=[
                    {"role": "system", "content": prompt},
                    {"role": "user", "content": "Clip transcript:\n" + transcript[:4000]},
                ],
            )
            payload = json.loads(response.message.content)


            print(
                f"Headline attempt {attempt} raw response: {payload}",
                flush=True,
            )

            return normalize_headline(payload.get("headline", ""))

        except Exception as exc:
            last_error = str(exc)
            print(
                f"Headline attempt {attempt}/2 failed: {last_error}",
                flush=True,
            )

    raise ValueError(last_error or "Ollama did not return a usable title")

def find_videos(value: str) -> list[Path]:
    if any(char in value for char in "*?["):
        # Previous versions accept a glob relative to the finished directory.
        if Path(value).is_absolute():
            raise ValueError("Use a relative glob such as '19-day-solo-*-styled.mp4'")
        matches = sorted(FINISHED.glob(value.removeprefix("finished/")))
    else:
        path = Path(value).expanduser()
        if path.is_file():
            matches = [path.resolve()]
        else:
            matches = [FINISHED / path.name] if (FINISHED / path.name).is_file() else []
    return [p for p in matches if p.name.endswith("-styled.mp4")]


def get_paths(video: Path):
    base = video.name.removesuffix("-styled.mp4")
    return (
        SUBTITLES / f"{base}-vertical.srt",
        HEADLINES / f"{base}.txt",
        FINISHED / f"{base}-upload.mp4",
        base,
    )


def title_for(video: Path) -> str | None:
    srt, title_file, _, base = get_paths(video)
    if title_file.is_file():
        try:
            title = normalize_headline(title_file.read_text(encoding="utf-8"))
        except ValueError as exc:
            print(f"REVIEW NEEDED {video.name}: invalid saved headline: {exc}")
            return None
        print(f"HEADLINE {video.name}: {title}")
        return title
    if not srt.is_file():
        reason = f"Missing subtitle file: {srt}"
        transcript = ""
    else:
        transcript = spoken_words(srt)
        try:
            title = generate_headline(transcript)
            HEADLINES.mkdir(parents=True, exist_ok=True)
            title_file.write_text(title + "\n", encoding="utf-8")
            print(f"HEADLINE {video.name}: {title}")
            return title
        except Exception as exc:
            reason = str(exc)

    REVIEW.mkdir(parents=True, exist_ok=True)
    note = REVIEW / f"{base}.txt"
    note.write_text(
        f"Clip: {video.name}\nReason: {reason}\n\n"
        f"Transcript excerpt:\n{transcript[:2500]}\n\n"
        f"Write a truthful clip-specific headline in:\n{title_file}\n",
        encoding="utf-8",
    )
    print(f"REVIEW NEEDED {video.name}: {reason}")
    print(f"  See: {note}")
    return None


def render(video: Path, *, force: bool = False) -> bool:
    _, title_file, output, base = get_paths(video)
    if not title_file.is_file():
        print(f"REVIEW NEEDED: no headline for {video.name} (run generate)")
        return False
    try:
        title = normalize_headline(title_file.read_text(encoding="utf-8"))
    except ValueError as exc:
        print(f"REVIEW NEEDED {video.name}: {exc}")
        return False
    if output.is_file() and not force:
        print(f"Skipping existing upload: {output.name}")
        return True
    if not FONT.is_file():
        raise FileNotFoundError(f"Missing caption font: {FONT}")

    # One drawtext filter per line. A multiline textfile can display missing-glyph
    # boxes at line breaks on some FFmpeg/font combinations.
    lines = textwrap.wrap(title, width=24, break_long_words=False)
    text_filters = []
    for i, line in enumerate(lines):
        textfile = HEADLINES / f"{base}-display-{i + 1:02d}.txt"
        textfile.write_text(line, encoding="utf-8")  # No trailing newline.
        text_filters.append(
            f"drawtext=fontfile={FONT}:textfile={textfile}:"
            "fontcolor=white:fontsize=58:"
            "borderw=3:bordercolor=black@0.9:box=0:"
            f"x=(w-text_w)/2:y={190 + i * 75}"
        )

    icon = icon_file(title)
    # Overlay a PNG emoji image instead of asking the Lato text font to
    # display an emoji glyph. This also works with color emoji artwork.
    filter_graph = (
        "[0:v]" + ",".join(text_filters) + "[text];"
        "[1:v]format=rgba,scale=98:98[emoji];"
        "[text][emoji]overlay=x=(main_w-overlay_w)/2:y=65:shortest=1[v]"
    )
    tmp = FINISHED / f"{base}-upload.partial.mp4"
    print(f"Rendering: {output.name}", flush=True)
    try:
        subprocess.run(
            [
                "ffmpeg", "-hide_banner", "-nostdin", "-y",
                "-i", str(video), "-loop", "1", "-i", str(icon),
                "-filter_complex", filter_graph,
                "-map", "[v]", "-map", "0:a?",
                "-c:v", "libx264", "-preset", "veryfast", "-crf", "21",
                "-c:a", "copy", "-movflags", "+faststart",
                str(tmp),
            ],
            check=True,
        )
        tmp.replace(output)
    finally:
        tmp.unlink(missing_ok=True)
    print(f"Saved: {output.name}")
    return True


def install() -> None:
    pipeline = ROOT / "run_pipeline.py"
    if not pipeline.is_file():
        sys.exit(f"No pipeline found at {pipeline}")
    source = pipeline.read_text(encoding="utf-8")
    if 'str(ROOT / "add_headlines.py")' in source:
        print("Automatic headlines are already integrated into run_pipeline.py")
        return
    anchor = 'print(f"Finished. Created '
    lines = source.splitlines(keepends=True)
    matches = [i for i, line in enumerate(lines) if line.startswith(anchor)]
    if len(matches) != 1:
        sys.exit("Couldn't safely identify the end of the clip loop. Original file unchanged.")
    addition = (
        '    # Automatically generate a clip-specific headline and an upload copy.\n'
        '    subprocess.run(\n'
        '        [sys.executable, str(ROOT / "add_headlines.py"), "process",\n'
        '         str(ROOT / "finished" / f"{name}-styled.mp4")],\n'
        '        check=True,\n'
        '    )\n\n'
    )
    backup = ROOT / "run_pipeline.py.before-headlines"
    if not backup.exists():
        shutil.copy2(pipeline, backup)
    lines.insert(matches[0], addition)
    pipeline.write_text("".join(lines), encoding="utf-8")
    try:
        py_compile.compile(str(pipeline), doraise=True)
    except Exception:
        pipeline.write_text(source, encoding="utf-8")
        raise
    print(f"Installed automatic headlines in {pipeline}")
    print(f"Original backed up at {backup}")


def main() -> None:
    if len(sys.argv) == 2 and sys.argv[1] == "install":
        install()
        return
    if (len(sys.argv) not in (3, 4)
            or sys.argv[1] not in {"generate", "render", "process"}
            or (len(sys.argv) == 4 and sys.argv[3] != "--force")):
        sys.exit("Usage: python add_headlines.py generate|render|process FILE_OR_GLOB [--force], or: install")
    mode, spec = sys.argv[1:3]
    force = len(sys.argv) == 4
    videos = find_videos(spec)
    if not videos:
        sys.exit(f"No styled videos matched: {spec}")
    HEADLINES.mkdir(parents=True, exist_ok=True)
    for video in videos:
        if mode in {"generate", "process"} and title_for(video) is None:
            continue
        if mode in {"render", "process"}:
            render(video, force=force)


if __name__ == "__main__":
    main()
